    fun modificationSupports(modificationId: String, base: ItemPart): Boolean {
        val groups = modificationBaseGroups[modificationId].orEmpty()
        val ids = modificationBaseIds[modificationId].orEmpty()
        return (groups.isEmpty() && ids.isEmpty()) || base.group in groups || base.id in ids
    }

